export const scene: DialogueEntry[] = [
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "13:25。受控會談室。美空病房隔壁。觀察窗。透過玻璃可以看見病房裡面——十三歲的女孩。呼吸器。監測螢幕。三條線。很平。控制器左側的面板貼著五方封條。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "會談室裡多了一張測試台。上面放著——同型退役卡匣。製造商服務模擬器。固件版本一致的測試控制器。三樣東西。排列整齊。像手術前的器械盤。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪坐在觀察窗旁邊。日下部在她左側。琴音坐在對面。辯護人在琴音旁邊。藤川真理坐在末端。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "獨立系統安全人員站在測試台前。外部醫師站在觀察窗旁邊——他的視線在美空的監測螢幕和測試台之間來回。院內臨床保管方在控制器旁邊。司法保全在門邊。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "五方。全部到齊。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）Domain-P。公共安全域。美空卡匣上的兩個域之一。Domain-C 是臨床根——綁定 G07／03。撐住她的呼吸、自律、腦電。Domain-P 是公共權限——讓這張卡匣可以被鏡島使用。讓她的節奏可以被當成公共授權的一部分。琴音被告知的是——兩者不可分。拔掉 Domain-P 就等於拔掉 Domain-C。拔掉公共權限就等於殺死美空。今天要驗證的是——這是不是真的。", background: Background.Chapter_24_Ch24_Act5_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "13:30。獨立系統安全人員先開口。他的聲音很平。技術性。精確。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.SystemSecurity, character: "獨立系統安全人員", dialogue: "Domain-P 隔離驗證。先在同型退役硬體及模擬器上確認。不在美空身上直接執行未驗證命令。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他指向測試台。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.SystemSecurity, character: "獨立系統安全人員", dialogue: "同型退役卡匣。製造商服務模擬器。固件版本一致。測試控制器。三項獨立驗證環境。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他拿起退役卡匣。銀色。和美空床邊那枚一樣的型號。但指示窗是暗的。沒有綁定任何患者。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.SystemSecurity, character: "獨立系統安全人員", dialogue: "驗證項目。第一——QUARANTINE-P 只修改 Domain-P 執行許可。不影響 Domain-C。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他把退役卡匣插入測試控制器。模擬器啟動。螢幕上開始跑數據。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.SystemSecurity, character: "獨立系統安全人員", dialogue: "第二——Domain-C 有獨立供電。獨立時鐘。獨立重置域。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "螢幕上列出三條獨立電力軌。三個獨立時鐘源。兩個獨立重置迴路。Domain-P 和 Domain-C——不在同一條電力線上。不在同一個時鐘上。不在同一個重置域裡。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）獨立供電。獨立時鐘。獨立重置。它們在同一個外殼裡。但——它們不是同一個機器。Domain-P 可以被關掉。Domain-C 可以繼續跑。物理上。電路上。邏輯上。它們——可以分開。", background: Background.Chapter_24_Ch24_Act5_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "13:40。獨立系統安全人員繼續。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.SystemSecurity, character: "獨立系統安全人員", dialogue: "第三——QUARANTINE-P 不觸發全卡匣 reboot。只修改 Domain-P 的執行許可旗標。Domain-C 不重啟。不重新初始化。不重新綁定。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他在模擬器上執行 QUARANTINE-P。螢幕上——Domain-P 的執行許可從 ENABLED 變成 DISABLED。Domain-C 的狀態列——沒有變化。沒有重啟。沒有重新初始化。心跳。時鐘。重置域。全部——UNCHANGED。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.SystemSecurity, character: "獨立系統安全人員", dialogue: "第四——不改變患者綁定。Domain-C 仍綁定測試患者。不重新綁定。不解除綁定。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他頓了一下。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.SystemSecurity, character: "獨立系統安全人員", dialogue: "第五——不觸發中央 fallback。隔離操作不產生 fallback 信號。不產生告警。不產生狀態變更通知。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "螢幕上——中央 fallback 狀態列。UNCHANGED。沒有信號。沒有告警。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.SystemSecurity, character: "獨立系統安全人員", dialogue: "第六——不接受遠端 institutional root 回退同一隔離狀態。隔離一旦生效——本地 revocation epoch 提升。遠端 root 無法降低 epoch。無法遠端恢復 Domain-P 執行許可。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他從模擬器上發送了一個遠端 institutional root 回退請求。螢幕上——REJECTED。LOCAL REVOCATION EPOCH — INCREMENTED。REMOTE RE-ENABLE — PROHIBITED。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "13:50。六項驗證全部完成。獨立系統安全人員收起退役卡匣。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.SystemSecurity, character: "獨立系統安全人員", dialogue: "同型硬體驗證完成。QUARANTINE-P 安全。Domain-C 不受影響。不可遠端逆轉。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他看了一眼外部醫師。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.SystemSecurity, character: "獨立系統安全人員", dialogue: "模擬器與現場固件版本一致。無 mismatch。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "確認。模擬器結果可作為現場執行依據。", background: Background.Chapter_24_Ch24_Act5_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "13:55。外部醫師走到觀察窗前。他看著美空的監測螢幕。呼吸。腦電。自律。三條線。沒有變化。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "醫療停止條件。", background: Background.Chapter_24_Ch24_Act5_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他的聲音變了。不是更大。是——更慢。像在確認每一個字都不會被誤解。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "任何下列情況出現——立即停止。Domain-C 心跳改變。控制器重置。美空腦電、自律或呼吸出現預定警報。中央 fallback 狀態改變。本地匯流排出現未預期寫入。模擬器與現場固件不一致。", background: Background.Chapter_24_Ch24_Act5_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他看著院內臨床保管方。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "監測——外部醫療獨立讀取。不使用設施內部系統。即時。", background: Background.Chapter_24_Ch24_Act5_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.ClinicalCustodian, character: "院內臨床保管方", dialogue: "確認。院內臨床保管方在位操作見證。設備實體安全由院方維護。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "14:00。獨立系統安全人員看著在場所有人。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.SystemSecurity, character: "獨立系統安全人員", dialogue: "五方共同執行。各自只提供自己的權限。不可互相替代。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他逐一確認。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.SystemSecurity, character: "獨立系統安全人員", dialogue: "患者代理授權——藤川真理。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "真理站起來。她的手放在桌面上。很穩。不是因為不害怕。是因為——已經害怕了四年。害怕到了盡頭以後，剩下的只有姿勢。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.FujikawaMari, character: "藤川真理", dialogue: "患者代理授權。藤川美空。G07／03。授權 Domain-P 隔離操作。條件——Domain-C 不受影響。不拔除卡匣。不改變患者綁定。五方共同控制。", background: Background.Chapter_24_Ch24_Act5_S0, portrait: Portrait.FujikawaMari_Determined },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她簽名。時間戳。她的筆跡很穩。像她已經在心裡簽過一千遍了。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.SystemSecurity, character: "獨立系統安全人員", dialogue: "外部醫療安全 share。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "外部醫療安全 share。確認醫療停止條件。確認獨立監測。確認美空生理狀態穩定。簽署範圍——醫療安全。", background: Background.Chapter_24_Ch24_Act5_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他簽名。時間戳。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.SystemSecurity, character: "獨立系統安全人員", dialogue: "獨立系統安全 share。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他簽自己的部分。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.SystemSecurity, character: "獨立系統安全人員", dialogue: "獨立系統安全 share。確認硬體隔離域。確認 Domain-P 與 Domain-C 可分離。確認 QUARANTINE-P 不可遠端逆轉。簽署範圍——技術授權。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他簽名。時間戳。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.SystemSecurity, character: "獨立系統安全人員", dialogue: "院內臨床保管方執行。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.ClinicalCustodian, character: "院內臨床保管方", dialogue: "院內臨床保管方執行。實體設備操作由院方執行。在位見證。禁止單人解除。簽署範圍——設備操作。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他簽名。時間戳。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.SystemSecurity, character: "獨立系統安全人員", dialogue: "司法保全全程記錄。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.JudicialPreservation, character: "司法保全", dialogue: "司法保全全程記錄。每一項。時間戳。證據鏈完整。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他簽名。時間戳。五方。全部完成。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "14:10。會談室裡安靜了。所有簽章到位。所有停止條件設定。所有監測啟動。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "琴音坐在對面。她沒有簽。她不是共同控制者。她是——觀察者。辯護人在她旁邊。她看著觀察窗後面的美空。十三歲的女孩。呼吸很慢。很穩。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）她在看。她在看——他們要做什麼。她被告知的是——兩域不可分。拔掉 Domain-P 就等於殺死美空。她為了這個——穿過那件衣服。拿過那把刀。刺過那個人。現在——她要看著他們在她妹妹的卡匣上執行一個她被告知不可能的操作。", background: Background.Chapter_24_Ch24_Act5_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "14:15。獨立系統安全人員走到觀察窗後面的病房裡。院內臨床保管方跟在後面。外部醫師留在會談室——他的眼睛盯著監測螢幕的即時讀數。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "透過觀察窗，澪看見獨立系統安全人員走到床側控制器旁邊。他沒有打開封條。封條上有一個預留的操作口——只夠插入探測器。不夠拔除卡匣。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他插入原位操作探測器。不拔除。不碰觸卡匣。只透過操作口執行。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "14:20。他開始執行。螢幕上——Domain-P 的狀態列開始變化。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "EXECUTION — DISABLED。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "會談室裡沒有人發出聲音。外部醫師的眼睛沒有離開監測螢幕。美空的呼吸——沒有變化。腦電——沒有變化。自律——沒有變化。三條線。很平。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "SESSION MATERIAL — ZEROIZED。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "Domain-P 的 session material 被清除。不是關閉。是——清零。像把一把鑰匙熔掉。不是鎖上門。是——鑰匙不存在了。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "REVOCATION EPOCH — INCREMENTED／LOCAL。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "本地撤銷紀元提升。這枚卡匣的 Domain-P——從現在起——被標記為一個新的、更高的 epoch。任何舊的授權——都會被這個 epoch 拒絕。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "REMOTE RE-ENABLE — PROHIBITED。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "遠端恢復——被禁止。不是暫停。不是等待確認。是——禁止。制度級 root 不能從遠端降低這個 epoch。不能從遠端恢復 Domain-P 的執行許可。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "14:25。螢幕上列出完整結果。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "```text DOMAIN-P EXECUTION             DISABLED SESSION MATERIAL      ZEROIZED REVOCATION EPOCH      INCREMENTED／LOCAL REMOTE RE-ENABLE      PROHIBITED REPROVISION           PHYSICAL SERVICE + PATIENT PROCESS FORENSIC READ         ALLOWED AUDIT                  IMMUTABLE", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "DOMAIN-C STATUS                 UNCHANGED PATIENT BINDING        G07／03 CLINICAL SIGNING       ACTIVE CLOCK／RESET DOMAIN    UNCHANGED ```", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "DOMAIN-C。STATUS — UNCHANGED。PATIENT BINDING — G07／03。CLINICAL SIGNING — ACTIVE。CLOCK／RESET DOMAIN — UNCHANGED。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "什麼都沒有變。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "美空的心跳沒有變。呼吸沒有變。腦電沒有變。Domain-C 仍在簽署臨床數據。仍在綁定 G07／03。仍在跑。像什麼都沒發生過。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "外部醫師看著監測螢幕。他的肩膀——鬆了一點。不是放鬆。是——停止條件沒有觸發。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.ExternalDoctor, character: "外部醫師", dialogue: "美空生理數值——未超出預定波動範圍。Domain-C 狀態——未改變。停止條件——未觸發。", background: Background.Chapter_24_Ch24_Act5_S0, portrait: Portrait.ExternalDoctor_Base },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "14:30。獨立系統安全人員從病房走出來。他收起探測器。他看著在場所有人。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.SystemSecurity, character: "獨立系統安全人員", dialogue: "Domain-P 隔離完成。原位執行。未拔除卡匣。未改變患者綁定。Domain-C 狀態——UNCHANGED。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "司法保全在門邊記錄。每一項。時間戳。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.JudicialPreservation, character: "司法保全", dialogue: "原位執行完成。DOMAIN-P DISABLED。SESSION ZEROIZED。REVOCATION EPOCH INCREMENTED LOCAL。REMOTE RE-ENABLE PROHIBITED。DOMAIN-C UNCHANGED。五方見證。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "14:35。會談室裡安靜了。很長的安靜。空調的聲音填進縫隙。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "琴音看著觀察窗。她的表情——沒有變。但她的眼睛——在動。她在看監測螢幕。三條線。很平。她的嘴唇——動了一下。沒有發出聲音。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "然後她開口了。很輕。像在確認一件她不敢相信的事。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.ShiraishiKotone, character: "白石琴音", dialogue: "⋯⋯她沒事。", background: Background.Chapter_24_Ch24_Act5_S0, portrait: Portrait.ShiraishiKotone_Shocked },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "不是問句。是——陳述。是確認。是她親眼看著——Domain-P 被關掉了。session 被清零了。revocation epoch 被提升了。而美空——仍在呼吸。仍在心跳。Domain-C 仍在跑。什麼都沒有變。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.ShiraishiKotone, character: "白石琴音", dialogue: "妹妹的臨床根仍在。", background: Background.Chapter_24_Ch24_Act5_S0, portrait: Portrait.ShiraishiKotone_Shocked },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她停了一下。她的手指碰著自己的手腕。很輕。像在確認什麼已經不在那裡了——又像在確認什麼仍然在。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.ShiraishiKotone, character: "白石琴音", dialogue: "公共權限卻可以被關掉。", background: Background.Chapter_24_Ch24_Act5_S0, portrait: Portrait.ShiraishiKotone_Shocked },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她的聲音在最後一個字上裂開了。不是崩潰。是——四年來支撐她的那個信念，在這一刻被現場操作推翻了。她被告知的「兩者不可分」。她為之刺傷了一個人的「兩者不可分」。她以為拔掉公共權限就等於殺死美空的「兩者不可分」——", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）她在看。她在看——她被告知不可能的事，剛剛發生了。Domain-P 被關掉了。美空還在呼吸。臨床根仍在。公共權限不在了。可是——她的妹妹沒有死。她為了「不能分開」而做的事——刺傷千田。安裝卡匣。隱瞞母親。四年。如果——如果一開始就可以分開。如果一開始就有人告訴她——公共權限可以被關掉，而美空不會死——", background: Background.Chapter_24_Ch24_Act5_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "琴音沒有繼續說。她低下頭。她的頭髮垂下來。遮住了她的臉。她的肩膀——在抖。很輕。不是哭。是——比哭更深的地方在震動。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "辯護人看著她。他沒有說話。他只是——在她旁邊。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "14:40。獨立系統安全人員走到鏡島安全終端前。他在鍵盤上輸入。螢幕上——鏡島端的本地拒絕清單。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.SystemSecurity, character: "獨立系統安全人員", dialogue: "鏡島本地拒絕清單。加入——美空卡匣硬體序號。加入——本地 revocation epoch。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "螢幕上更新了。序號。epoch。兩項。被加入 KAGAMI-01 本地 denylist。維護終端拒絕清單。物理監控告警。提交前硬體核驗阻斷。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.SystemSecurity, character: "獨立系統安全人員", dialogue: "同一張卡匣——不能直接被帶往鏡島使用。序號被拒。epoch 被拒。任何提交前的硬體核驗——都會阻斷。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他頓了一下。他看著琴音。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.SystemSecurity, character: "獨立系統安全人員", dialogue: "CONTINUITY-0 也不能遠端復活這張卡匣。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "琴音抬起頭。她的眼睛紅了。但沒有眼淚。她看著獨立系統安全人員。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.SystemSecurity, character: "獨立系統安全人員", dialogue: "它無法降低本地 revocation epoch。無法恢復已清除的 Domain-P session material。無法改動 Domain-C。無法遠端解除 QUARANTINE-P。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他停了一下。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.SystemSecurity, character: "獨立系統安全人員", dialogue: "它若要重開鏡島——只能另造一把公共鑰匙。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "琴音看著他。看了很久。她的嘴唇動了一下。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.ShiraishiKotone, character: "白石琴音", dialogue: "⋯⋯另造一把。", background: Background.Chapter_24_Ch24_Act5_S0, portrait: Portrait.ShiraishiKotone_Sad },
    { characterId: CharacterId.SystemSecurity, character: "獨立系統安全人員", dialogue: "是。不能利用妹妹的卡匣。只能用另一枚空白制度級 token，或 KAGAMI-01 內建安全模組，重新簽發一個新的臨時 Domain-P。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "琴音低下頭。她的手指在桌面下握著自己的手腕。然後——鬆開了。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）兩者不可分。她被告知的。她相信的。她為之犯下不可原諒之事的——信念。今天——被推翻了。不是被說服。不是被辯論。是——被操作。被五方共同執行的、不可遠端逆轉的、原位隔離操作。Domain-P 被關掉了。Domain-C 仍在跑。美空仍在呼吸。公共鑰匙離開了病人。病人沒有死。可是——制度仍能另造一把公共鑰匙。終局威脅不是這張卡匣。是——制度本身仍能簽發新的公共 token。今天的勝利是真的。但它不是終局。", background: Background.Chapter_24_Ch24_Act5_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "14:50。藤川真理一直坐在末端。她沒有說話。她的手放在膝蓋上。她看著觀察窗後面的美空。十三歲的女孩。呼吸很慢。很穩。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "她的手——很穩。和簽名時一樣穩。不是因為不害怕。是因為——她害怕了四年。今天——她害怕的那件事沒有發生。Domain-P 被關掉了。美空還在。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "15:00。獨立系統安全人員完成鏡島端的更新。他收起終端。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.SystemSecurity, character: "獨立系統安全人員", dialogue: "Domain-P 隔離——完成。鏡島 denylist——更新。CONTINUITY-0 無法遠端復活同一卡匣。制度只能另簽新公共 token。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "他看了一眼澪。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.SystemSecurity, character: "獨立系統安全人員", dialogue: "這不是——所有公共權限消失。制度級根仍存在。emergency override 仍存在。另造公共 token 的能力——仍存在。今天的操作只做到一件事——這張卡匣。這枚序號。這個 epoch。不能被遠端復活。不能被帶往鏡島。不能被當成公共授權的一部分。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "⋯⋯我知道。", background: Background.Chapter_24_Ch24_Act5_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "15:10。會談室裡的人開始收拾。司法保全封存記錄。外部醫師最後看了一眼監測螢幕。數值穩定。三條線。很平。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "琴音站起來。她的膝蓋很僵。她走到觀察窗前。她看著裡面。美空。十三歲。呼吸很慢。很穩。控制器左側的封條還在。封條上的編號沒有變。五方簽章的位置沒有變。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "但封條下面——Domain-P 已經不在了。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.ShiraishiKotone, character: "白石琴音", dialogue: "⋯⋯不拔。", background: Background.Chapter_24_Ch24_Act5_S0, portrait: Portrait.ShiraishiKotone_Sad },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "和上次一樣。不是問句。是陳述。是確認。但這次——她的聲音裡多了一樣東西。不是釋懷。不是信任。是——她被告知的「不可能」剛剛發生了，而她的妹妹仍在呼吸。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "15:20。她走了。辯護人跟在她後面。門關上。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "澪坐在原位。她看著觀察窗。美空還在睡。呼吸器的節奏沒有變。監測螢幕上的三條線——很平。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.AsakuraMio, character: "朝倉澪", dialogue: "（內心）公共鑰匙離開了病人。病人沒有死。Domain-P 被關掉了。Domain-C 仍在跑。這是——行動高潮。不是終局。不是所有公共權限消失。不是 CONTINUITY-0 停止。是——一枚卡匣。一個序號。一個 epoch。被本地、不可遠端逆轉地隔離了。制度仍能另造一把鑰匙。可是——這一把。這一枚。這一張卡匣。不能再被利用了。美空的臨床根——不再同時是公共鑰匙的一部分了。", background: Background.Chapter_24_Ch24_Act5_S0, portrait: Portrait.AsakuraMio_Exhausted },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "15:25。她站起來。膝蓋很僵。她走向門口。走廊的螢光燈和病房裡一樣亮。", background: Background.Chapter_24_Ch24_Act5_S0 },
    { characterId: CharacterId.Narrator, character: "旁白", dialogue: "距下一次星期一 06:13——約一日十五小時十三分鐘。", background: Background.Chapter_24_Ch24_Act5_S0 },
];
